 for(const p of s.projects){if(p&&typeof p==='object'){p.funding=inferFunding(p);if(!Number.isInteger(p.year))p.year=inferYear(p);p.category||=s.categories[0]?.id||'CAT-001';p.extensions||=[];}}
 s.years||=[];for(const p of s.projects)if(Number.isInteger(p?.year)&&!s.years.includes(p.year))s.years.push(p.year);
 for(const r of s.reports){if(r&&typeof r==='object'&&r.id!=='EMPTY'){r.funding=inferFunding(r);r.year=inferYear(r,s.years[0]||2569);if(!s.years.includes(r.year))s.years.push(r.year);if((!r.start||!r.end)&&(r.sourceTitle||r.title)){const rng=parseThaiWeekRange(r.sourceTitle||r.title,r.year);if(rng){r.start||=rng.start;r.end||=rng.end;r.reference||=rng.reference;}}r.reference||=r.end;}}
